    photographs:{status:'verified',sourceId:'src-commons-sannati-photo-2021',items:[{sourceId:'src-commons-sannati-photo-2021',capturedAt:'2021-01-28T13:59:33+05:30',creator:'Ms Sarah Welch',license:'CC0 1.0',pageUrl:'https://commons.wikimedia.org/wiki/File:3rd_century_BCE_to_7th_century_CE_Sannathi_Sannati_Sonti_ancient_city_archaeological_site,_Karnataka_India_-_97.jpg',latitude:16.835889,longitude:76.933806,depicts:name('Sannati archaeological-site field condition','ಸನ್ನತಿ ಪುರಾತತ್ತ್ವ ತಾಣದ ಕ್ಷೇತ್ರ ಸ್ಥಿತಿ')},{sourceId:'src-commons-kanaganahalli-inscription-2024',capturedAt:'2024-12-08',creator:'Anandajoti Bhikkhu',license:'CC BY-SA 4.0',pageUrl:'https://commons.wikimedia.org/wiki/File:015_Asoka_Inscription,_Kanaganahalli.jpg',depicts:name('Relocated “Raya Asoko” inscribed panel in the Telangana State Archaeology Museum','ತೆಲಂಗಾಣ ರಾಜ್ಯ ಪುರಾತತ್ತ್ವ ಸಂಗ್ರಹಾಲಯದಲ್ಲಿರುವ ಸ್ಥಳಾಂತರಿತ “ರಾಯ ಅಸೋಕೋ” ಶಾಸನ ಫಲಕ')}]},
