const makeResolution = (id, sourceId, locator) => ({
  corpus:{status:'verified',sourceId,locator},
  itemEdition:unresolved('An individual corpus item or definitive edition must be selected.','ಪ್ರತ್ಯೇಕ ಶಾಸನಸಂಪುಟ ದಾಖಲೆ ಅಥವಾ ನಿರ್ಣಾಯಕ ಆವೃತ್ತಿಯನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕು.'),
  coordinates:unresolved('Exact present-location coordinates need an authority register or documented field observation.','ನಿಖರ ಪ್ರಸ್ತುತ ಸ್ಥಳದ ನಿರ್ದೇಶಾಂಕಗಳಿಗೆ ಅಧಿಕೃತ ನೋಂದಣಿ ಅಥವಾ ದಾಖಲಿತ ಕ್ಷೇತ್ರ ಅವಲೋಕನ ಬೇಕಾಗಿದೆ.'),
  transcription:unresolved('A line-by-line diplomatic transcription has not been captured.','ಸಾಲು-ಸಾಲಿನ ಮೂಲಾಕ್ಷರ ಪಾಠವನ್ನು ಇನ್ನೂ ದಾಖಲಿಸಿಲ್ಲ.'),
  translation:unresolved('A source-checked Kannada and English translation has not been captured.','ಆಕರ-ಪರಿಶೀಲಿತ ಕನ್ನಡ ಮತ್ತು ಇಂಗ್ಲಿಷ್ ಅನುವಾದವನ್ನು ಇನ್ನೂ ದಾಖಲಿಸಿಲ್ಲ.'),
  presentCondition:unresolved('A dated, site-specific condition report is required.','ದಿನಾಂಕಿತ, ತಾಣ-ನಿರ್ದಿಷ್ಟ ಸ್ಥಿತಿ ವರದಿ ಅಗತ್ಯ.'),
  authority:unresolved('Protection status and present managing authority require an official register match.','ಸಂರಕ್ಷಣಾ ಸ್ಥಿತಿ ಮತ್ತು ಪ್ರಸ್ತುತ ನಿರ್ವಹಣಾ ಪ್ರಾಧಿಕಾರಕ್ಕೆ ಅಧಿಕೃತ ನೋಂದಣಿ ಹೊಂದಿಕೆ ಬೇಕಾಗಿದೆ.'),
  photographs:unresolved('A dated, licensed, item-specific field photograph has not been attached.','ದಿನಾಂಕಿತ, ಪರವಾನಗಿಯುಳ್ಳ, ದಾಖಲೆ-ನಿರ್ದಿಷ್ಟ ಕ್ಷೇತ್ರ ಛಾಯಾಚಿತ್ರವನ್ನು ಇನ್ನೂ ಜೋಡಿಸಿಲ್ಲ.'),
  ...candidateResolutionOverrides[id],
})

const promotionEvidenceFields = ['itemEdition','coordinates','transcription','translation','presentCondition','authority','photographs']
const evidenceRequestTemplates={
  itemEdition:{submissionType:'corpus-edition',requiredFields:['sourceId','series','volume','number','pageOrPlate'],instruction:name('Supply the exact edition, item number and printed page or plate image.','ನಿಖರ ಆವೃತ್ತಿ, ದಾಖಲೆ ಸಂಖ್ಯೆ ಮತ್ತು ಮುದ್ರಿತ ಪುಟ ಅಥವಾ ಫಲಕದ ಚಿತ್ರವನ್ನು ನೀಡಿ.')},
  coordinates:{submissionType:'authority-coordinate',requiredFields:['latitude','longitude','precision','authorityName','authorityRecordId','sourceUrl'],instruction:name('Supply a numeric point or protected-boundary coordinate issued by ASI, NMA, State Archaeology, the managing museum, or a signed field survey.','ASI, NMA, ರಾಜ್ಯ ಪುರಾತತ್ವ, ನಿರ್ವಹಣಾ ಸಂಗ್ರಹಾಲಯ ಅಥವಾ ಸಹಿ ಮಾಡಿದ ಕ್ಷೇತ್ರ ಸಮೀಕ್ಷೆ ನೀಡಿದ ಸಂಖ್ಯಾತ್ಮಕ ಬಿಂದು ಅಥವಾ ಸಂರಕ್ಷಿತ ಗಡಿ ನಿರ್ದೇಶಾಂಕವನ್ನು ನೀಡಿ.')},
  transcription:{submissionType:'line-transcription',requiredFields:['sourceId','locator','script','lines','damageNotation'],instruction:name('Transcribe line by line from the cited item image and mark loss, restoration and uncertain aksharas.','ಉಲ್ಲೇಖಿತ ದಾಖಲೆ ಚಿತ್ರದ ಆಧಾರದಲ್ಲಿ ಸಾಲು-ಸಾಲಾಗಿ ಪಾಠ ದಾಖಲಿಸಿ; ನಷ್ಟ, ಪುನರ್‌ರಚನೆ ಮತ್ತು ಅನುಮಾನಿತ ಅಕ್ಷರಗಳನ್ನು ಗುರುತಿಸಿ.')},
  translation:{submissionType:'independent-kannada-review',requiredFields:['reviewerUserId','sourceId','locator','lineAlignment','requiredChecks','attestation'],instruction:name('An independent epigraphist must review the Kannada against the cited text and record every required check.','ಸ್ವತಂತ್ರ ಶಾಸನತಜ್ಞರು ಉಲ್ಲೇಖಿತ ಪಾಠದೊಂದಿಗೆ ಕನ್ನಡವನ್ನು ಪರಿಶೀಲಿಸಿ ಎಲ್ಲ ಅಗತ್ಯ ತಪಾಸಣೆಗಳನ್ನು ದಾಖಲಿಸಬೇಕು.')},
  presentCondition:{submissionType:'dated-condition-survey',requiredFields:['observedAt','observer','surface','shelter','access','threats','authorityContact'],instruction:name('Record a dated whole-item and whole-site condition observation; historical reports and cropped photographs are insufficient.','ದಿನಾಂಕಿತ ಸಂಪೂರ್ಣ ದಾಖಲೆ ಮತ್ತು ಸಂಪೂರ್ಣ ತಾಣದ ಸ್ಥಿತಿ ಅವಲೋಕನ ದಾಖಲಿಸಿ; ಹಳೆಯ ವರದಿ ಮತ್ತು ಕತ್ತರಿಸಿದ ಚಿತ್ರಗಳು ಸಾಕಾಗುವುದಿಲ್ಲ.')},
  authority:{submissionType:'protection-register-match',requiredFields:['authorityName','designation','registerId','sourceUrl','checkedAt'],instruction:name('Match the item to a current official protection register and managing authority.','ದಾಖಲೆಯನ್ನು ಪ್ರಸ್ತುತ ಅಧಿಕೃತ ಸಂರಕ್ಷಣಾ ನೋಂದಣಿ ಮತ್ತು ನಿರ್ವಹಣಾ ಪ್ರಾಧಿಕಾರಕ್ಕೆ ಹೊಂದಿಸಿ.')},
  photographs:{submissionType:'licensed-photo-set',requiredFields:['capturedAt','creator','license','sourceUrl','depicts','coordinates'],instruction:name('Provide dated, reusable photographs of the inscription, context, shelter, access and visible threats with creator and licence.','ಶಾಸನ, ಸಂದರ್ಭ, ಆಶ್ರಯ, ಪ್ರವೇಶ ಮತ್ತು ಕಾಣುವ ಅಪಾಯಗಳ ದಿನಾಂಕಿತ ಮರುಬಳಕೆ ಯೋಗ್ಯ ಚಿತ್ರಗಳನ್ನು ಕರ್ತೃ ಮತ್ತು ಪರವಾನಗಿಯೊಂದಿಗೆ ನೀಡಿ.')},
}

const makePromotionReview = resolution => {
  const completedEvidence=promotionEvidenceFields.filter(field=>resolution[field]?.status==='verified')
  const blockingEvidence=promotionEvidenceFields.filter(field=>resolution[field]?.status!=='verified')
  const translationSections=resolution.translation?.sections||[]
  const sourceLineCount=translationSections.reduce((total,section)=>total+(section.en?.length||0),0)
  const kannadaLineCount=translationSections.reduce((total,section)=>total+(section.kn?.length||0),0)
  const linesAligned=translationSections.length>0&&translationSections.every(section=>Array.isArray(section.en)&&Array.isArray(section.kn)&&section.en.length===section.kn.length)
  const translationDraftReady=resolution.transcription?.status==='verified'&&linesAligned
  const ready=completedEvidence.length===promotionEvidenceFields.length
  return {
    target:'public-inscription',
    status:ready?'ready-for-promotion':translationDraftReady?'translation-review':'evidence-capture',
    completedEvidence,
    blockingEvidence,
    evidenceRequests:blockingEvidence.map(field=>({field,...evidenceRequestTemplates[field]})),
    requiredEvidence:promotionEvidenceFields,
    translation:{
      languageCode:'kn',
      status:resolution.translation?.status==='verified'?'approved':translationDraftReady?'awaiting-independent-review':'awaiting-source-capture',
      independentReviewerRequired:true,
      requiredChecks:['sourceMatch','semanticFidelity','namesAndDates','historicalTerminology','lineCompleteness','reviewerAttestation'],
      reviewPacket:{status:translationDraftReady?'ready-for-independent-review':'incomplete',sourceId:resolution.translation?.sourceId||null,locator:resolution.translation?.locator||null,sectionCount:translationSections.length,sourceLineCount,kannadaLineCount,lineAlignment:linesAligned?'aligned':'mismatch',reviewer:null,reviewedAt:null,decision:null},
    },
    note:name('Promotion is blocked until the item text is captured from the cited edition, Kannada is independently approved, and every site-evidence field is verified.','ಉಲ್ಲೇಖಿತ ಆವೃತ್ತಿಯಿಂದ ಪಾಠವನ್ನು ದಾಖಲಿಸಿ, ಕನ್ನಡ ಅನುವಾದವನ್ನು ಸ್ವತಂತ್ರವಾಗಿ ಅನುಮೋದಿಸಿ ಮತ್ತು ತಾಣದ ಪ್ರತಿಯೊಂದು ಸಾಕ್ಷ್ಯ ಕ್ಷೇತ್ರವನ್ನು ಪರಿಶೀಲಿಸುವವರೆಗೆ ಪ್ರಕಟಣೆ ತಡೆಹಿಡಿಯಲಾಗಿದೆ.'),
  }
}

const candidate = (id, en, kn, placeEn, placeKn, from, to, era, precision, languages, scripts, sourceId, locator, noteEn, noteKn) => {
  const resolution=makeResolution(id,sourceId,locator)
  const citations=[cite(sourceId,locator)]
  ;Object.values(resolution).forEach(evidence=>{
    if(!evidence?.sourceId||citations.some(item=>item.sourceId===evidence.sourceId))return
    citations.push(cite(evidence.sourceId,evidence.locator||primaryEvidenceLocator(evidence)))
  })
  ;Object.values(resolution).flatMap(evidence=>evidence?.alternateSources||[]).forEach(alternate=>{
    if(!alternate.sourceId||citations.some(item=>item.sourceId===alternate.sourceId))return
    citations.push(cite(alternate.sourceId,alternate.locator||'Alternate digitised edition'))
  })
  ;Object.values(resolution).flatMap(evidence=>evidence?.supportingSourceIds||[]).forEach(supportingSourceId=>{
    if(!supportingSourceId||citations.some(item=>item.sourceId===supportingSourceId))return
    citations.push(cite(supportingSourceId,'Supporting authority or condition evidence'))
  })
  return {
    id:`epigraphy-candidate-${id}`, name:name(en,kn), place:name(placeEn,placeKn),
    date:{from,to,era,precision}, languages, scripts, coordinates:resolution.coordinates.status==='verified'?{latitude:resolution.coordinates.latitude,longitude:resolution.coordinates.longitude,precision:resolution.coordinates.precision}:null,
    readiness:resolution.itemEdition.status==='verified'?'item-located':'corpus-located', citations,
    researchNote:name(noteEn,noteKn), resolution, promotionReview:makePromotionReview(resolution), review:review('needs-review'),
  }
}

const primaryEvidenceLocator = evidence => evidence.designation?.en||evidence.description?.en||evidence.note?.en||'Supporting evidence'

